import * as z from "zod";
//#region src/db/to-zod.ts
/**
* Static lookup keeps `zod` tree-shakeable. `z[field.type]()` forces bundlers
* to retain every `zod` export, including all locales.
*/
const scalarSchemas = {
	string: z.string,
	number: z.number,
	boolean: z.boolean,
	date: z.date
};
function toZodSchema({ fields, isClientSide }) {
	const zodFields = Object.keys(fields).reduce((acc, key) => {
		const field = fields[key];
		if (!field) return acc;
		if (isClientSide && field.input === false) return acc;
		let schema;
		if (field.type === "json") schema = z.json();
		else if (field.type === "string[]" || field.type === "number[]") schema = z.array(field.type === "string[]" ? z.string() : z.number());
		else if (Array.isArray(field.type)) schema = z.any();
		else schema = scalarSchemas[field.type]();
		if (field?.required === false) schema = schema.nullish();
		if (!isClientSide && field?.returned === false) return acc;
		return {
			...acc,
			[key]: schema
		};
	}, {});
	return z.object(zodFields);
}
//#endregion
export { toZodSchema };
